       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (rd_addr_w_wb[0]));
  CDN_flop \wb_rd_addr_out_reg[1] (.clk (clk), .d (rd_addr_w_ex[1]),
       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (rd_addr_w_wb[1]));
  CDN_flop \wb_rd_addr_out_reg[2] (.clk (clk), .d (rd_addr_w_ex[2]),
       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (rd_addr_w_wb[2]));
  CDN_flop \wb_rd_addr_out_reg[3] (.clk (clk), .d (rd_addr_w_ex[3]),
       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (rd_addr_w_wb[3]));
  CDN_flop \wb_rd_addr_out_reg[4] (.clk (clk), .d (rd_addr_w_ex[4]),
       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (rd_addr_w_wb[4]));
  CDN_flop wb_reg_write_en_out_reg(.clk (clk), .d (reg_write_en_ex),
       .sena (1'b1), .aclr (rst), .apre (1'b0), .srl (1'b0), .srd
       (1'b0), .q (reg_enable_wb));
endmodule

`ifdef RC_CDN_GENERIC_GATE
`else
module CDN_flop(clk, d, sena, aclr, apre, srl, srd, q);
  input clk, d, sena, aclr, apre, srl, srd;
  output q;
  wire clk, d, sena, aclr, apre, srl, srd;
  wire q;
  reg  qi;
  assign #1 q = qi;
  always 
    @(posedge clk or posedge apre or posedge aclr) 
      if (aclr) 
        qi <= 0;
      else if (apre) 
          qi <= 1;
        else if (srl) 
            qi <= srd;
          else begin
            if (sena) 
              qi <= d;
          end
  initial 
    qi <= 1'b0;
endmodule
`endif
